<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/dashboard_layout.php';
$user = require_role('delivery_agent');
$profileStatement=db()->prepare('SELECT * FROM delivery_agent_profiles WHERE user_id=?');$profileStatement->execute([$user['id']]);$profile=$profileStatement->fetch();
$reviewAverage = sf_query('SELECT AVG(rating) FROM reviews_ratings WHERE agent_id=?', [$user['id']])->fetchColumn();
$profile['rating'] = $reviewAverage !== null && $reviewAverage !== false ? number_format((float)$reviewAverage,2) : 'Not rated';
$performanceStatement=db()->prepare("SELECT COUNT(*) total_jobs,COALESCE(SUM(order_status='Completed'),0) completed_jobs,COALESCE(SUM(order_status='Cancelled'),0) cancelled_jobs,COALESCE(SUM(CASE WHEN order_status='Completed' THEN quantity_liters ELSE 0 END),0) delivered_liters FROM orders WHERE delivery_agent_id=?");$performanceStatement->execute([$user['id']]);$performance=$performanceStatement->fetch();
$completionRate=(int)$performance['total_jobs']>0?round(((int)$performance['completed_jobs']/(int)$performance['total_jobs'])*100):0;
$agentLevel=1+(int)floor((int)$performance['completed_jobs']/5);$levelProgress=((int)$performance['completed_jobs']%5)*20;
$todayStatement=db()->prepare("SELECT COALESCE(SUM(total_payout),0) amount,COUNT(*) trips FROM delivery_earnings WHERE agent_id=? AND DATE(created_at)=CURDATE()");$todayStatement->execute([$user['id']]);$today=$todayStatement->fetch();
$weekStatement=db()->prepare('SELECT COALESCE(SUM(total_payout),0) FROM delivery_earnings WHERE agent_id=? AND created_at>=DATE_SUB(CURDATE(),INTERVAL 6 DAY)');$weekStatement->execute([$user['id']]);$weekly=(float)$weekStatement->fetchColumn();
$lifetimeStatement=db()->prepare("SELECT COALESCE(SUM(total_payout),0) lifetime,COALESCE(SUM(CASE WHEN payout_status='Pending' THEN total_payout ELSE 0 END),0) pending FROM delivery_earnings WHERE agent_id=?");$lifetimeStatement->execute([$user['id']]);$lifetime=$lifetimeStatement->fetch();
$jobsStatement=db()->prepare("SELECT o.*,u.full_name customer_name,u.phone customer_phone FROM orders o JOIN users u ON u.id=o.customer_id WHERE o.delivery_agent_id=? AND o.order_status NOT IN ('Completed','Cancelled') ORDER BY o.created_at");$jobsStatement->execute([$user['id']]);$jobs=$jobsStatement->fetchAll();
$available=db()->query("SELECT o.*,u.full_name customer_name FROM orders o JOIN users u ON u.id=o.customer_id WHERE o.delivery_agent_id IS NULL AND o.order_status='Pending' ORDER BY o.created_at LIMIT 5")->fetchAll();
$available = sf_approved((int)$user['id']) && !empty($profile['is_online']) ? $available : [];
$earningsStatement=db()->prepare('SELECT de.*,o.tracking_code,o.quantity_liters FROM delivery_earnings de JOIN orders o ON o.id=de.order_id WHERE de.agent_id=? ORDER BY de.created_at DESC LIMIT 8');$earningsStatement->execute([$user['id']]);$earnings=$earningsStatement->fetchAll();
dashboard_start('Delivery Dispatch Hub','dashboard',$user);
?>
<section class="welcome-panel"><div><span class="eyebrow">Partner operations</span><h2>Your road. Your earnings.</h2><p>Accept nearby dispatches, progress deliveries and inspect every payout component.</p></div><form method="post" action="<?= url('delivery/toggle_status.php') ?>" data-duty-form><?= csrf_field() ?><button class="online-switch <?= $profile&&$profile['is_online']?'online':'' ?>" type="submit" data-duty-button><i class="fa-solid fa-power-off"></i><span><?= $profile&&$profile['is_online']?'Go Offline':'Go Online' ?></span></button></form></section>
<section class="agent-command-card">
    <div class="agent-identity"><div class="agent-avatar"><span><?= e(strtoupper(substr($user['full_name'],0,1))) ?></span><i></i></div><div><span class="eyebrow"><?= sf_approved((int)$user['id']) ? 'Approved delivery partner' : 'Approval pending' ?></span><h2><?= e($user['full_name']) ?></h2><p><i class="fa-solid fa-motorcycle"></i> <?= e($profile['vehicle_plate']??'Vehicle pending') ?> <b>·</b> <i class="fa-solid fa-star"></i> <?= e($profile['rating']??'5.00') ?></p></div></div>
    <div class="agent-level"><div class="level-head"><span>Road Captain · Level <?= $agentLevel ?></span><strong><?= $levelProgress ?>%</strong></div><div class="level-track"><i style="width:<?= $levelProgress ?>%"></i></div><small><?= 5-((int)$performance['completed_jobs']%5) ?> completed trips to the next level</small></div>
    <div class="agent-performance"><div><strong><?= $completionRate ?>%</strong><span>Completion</span></div><div><strong><?= number_format((float)$performance['delivered_liters'],1) ?> L</strong><span>Fuel delivered</span></div><div><strong><?= (int)$performance['completed_jobs'] ?></strong><span>Completed trips</span></div></div>
    <a class="btn btn-small btn-secondary" href="<?= url('delivery/profile.php') ?>">View Profile <i class="fa-solid fa-arrow-right"></i></a>
</section>
<section class="metrics-grid"><article class="metric-card"><span class="metric-icon"><i class="fa-solid fa-indian-rupee-sign"></i></span><div><strong data-counter="<?= (float)$today['amount'] ?>" data-prefix="₹">₹0</strong><span>Today's Earnings · <?= (int)$today['trips'] ?> trips</span></div></article><article class="metric-card"><span class="metric-icon"><i class="fa-solid fa-calendar-week"></i></span><div><strong data-counter="<?= $weekly ?>" data-prefix="₹">₹0</strong><span>Weekly Earnings</span></div></article><article class="metric-card"><span class="metric-icon"><i class="fa-solid fa-chart-line"></i></span><div><strong data-counter="<?= (float)$lifetime['lifetime'] ?>" data-prefix="₹">₹0</strong><span>Lifetime Earnings</span></div></article><article class="metric-card"><span class="metric-icon"><i class="fa-solid fa-wallet"></i></span><div><strong data-counter="<?= (float)$lifetime['pending'] ?>" data-prefix="₹">₹0</strong><span>Pending Payout</span></div></article></section>
<div class="dashboard-grid"><section class="panel"><div class="panel-head"><h2>Active Dispatches</h2><a href="<?= url('delivery/active_deliveries.php') ?>">Open dispatch screen <i class="fa-solid fa-arrow-right"></i></a></div><?php if(!$jobs): ?><div class="empty-state"><i class="fa-solid fa-route"></i><h3>No active delivery</h3><p>Accept an available request to begin.</p></div><?php else: ?><?php foreach($jobs as $job): ?><article class="job-card"><div class="panel-head"><div><strong style="color:var(--text)"><?= e($job['tracking_code']) ?></strong><small style="display:block"><?= e($job['fuel_type']) ?> · <?= e($job['quantity_liters']) ?> L</small></div><span class="badge <?= status_class($job['order_status']) ?>"><?= e($job['order_status']) ?></span></div><div class="route-point"><i class="fa-solid fa-location-dot"></i><div><small>Deliver to <?= e($job['customer_name']) ?></small><strong><?= e($job['delivery_address']) ?></strong></div></div></article><?php endforeach; ?><?php endif; ?></section><aside class="panel"><div class="panel-head"><h2>Available Jobs</h2><span class="badge warning"><?= count($available) ?> waiting</span></div><div class="quick-actions"><?php foreach($available as $job): ?><a class="quick-action" href="<?= url('delivery/active_deliveries.php') ?>"><i class="fa-solid fa-bolt"></i><div><strong><?= e($job['tracking_code']) ?> · <?= e($job['quantity_liters']) ?> L</strong><small><?= e($job['delivery_pincode']) ?> · <?= money($job['delivery_fee']) ?> delivery fee</small></div></a><?php endforeach; ?></div></aside></div>
<section class="panel"><div class="panel-head"><h2>Earnings Breakdown</h2><a href="<?= url('delivery/earnings.php') ?>">All payouts <i class="fa-solid fa-arrow-right"></i></a></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Order ID</th><th>Litres Pumped</th><th>Base Fee</th><th>Distance Bonus</th><th>Customer Tip</th><th>Total Earned</th></tr></thead><tbody><?php foreach($earnings as $earning): ?><tr><td><?= e(date('d M Y',strtotime($earning['created_at']))) ?></td><td><strong><?= e($earning['tracking_code']) ?></strong></td><td><?= e($earning['quantity_liters']) ?> L</td><td><?= money($earning['base_payout']) ?></td><td><?= money($earning['distance_bonus']) ?></td><td><?= money($earning['tip_amount']) ?></td><td class="money-tag"><?= money($earning['total_payout']) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php dashboard_end(); ?>
